package connect

import "errors"

// ResultOf computes the winner of a Hex / Polygon / CON-TAC-TIX game.
//
// The board is a parallelogram of hexagonal fields, given as a slice of rows
// (each row the same length). Player "O" plays from top to bottom and player
// "X" plays from left to right. The function returns "O" or "X" if that player
// has connected their two assigned sides, or "" if nobody has won.
func ResultOf(lines []string) (string, error) {
	if len(lines) == 0 {
		return "", errors.New("board must not be empty")
	}

	height := len(lines)
	width := len(lines[0])
	for i, l := range lines {
		if len(l) != width {
			return "", errors.New("board rows must all have the same length")
		}
		_ = i
	}

	board := make([][]byte, height)
	for r := 0; r < height; r++ {
		board[r] = []byte(lines[r])
	}

	// Neighbour offsets for the skewed hex grid. A cell (r, c) touches:
	//
	//        (r-1, c)   (r-1, c+1)
	//   (r, c-1)   .    (r, c+1)
	//        (r+1, c-1) (r+1, c)
	var dirs = [6][2]int{
		{0, -1}, // left
		{0, 1},  // right
		{-1, 0}, // up
		{-1, 1}, // up-right
		{1, -1}, // down-left
		{1, 0},  // down
	}

	// floodFill performs a breadth-first search over the connected region of
	// `player` stones that contains any of the seed cells, and reports whether
	// that region touches a cell for which `reached` is true.
	floodFill := func(player byte, seeds [][2]int, reached func(r, c int) bool) bool {
		visited := make([][]bool, height)
		for r := 0; r < height; r++ {
			visited[r] = make([]bool, width)
		}

		queue := make([][2]int, 0, height*width)
		for _, s := range seeds {
			r, c := s[0], s[1]
			if r < 0 || r >= height || c < 0 || c >= width {
				continue
			}
			if board[r][c] != player || visited[r][c] {
				continue
			}
			visited[r][c] = true
			queue = append(queue, s)
		}

		head := 0
		for head < len(queue) {
			cur := queue[head]
			head++
			r, c := cur[0], cur[1]
			if reached(r, c) {
				return true
			}
			for _, d := range dirs {
				nr, nc := r+d[0], c+d[1]
				if nr < 0 || nr >= height || nc < 0 || nc >= width {
					continue
				}
				if board[nr][nc] != player || visited[nr][nc] {
					continue
				}
				visited[nr][nc] = true
				queue = append(queue, [2]int{nr, nc})
			}
		}
		return false
	}

	// X plays from left to right: any X in the left column reaching the right column.
	xSeeds := make([][2]int, 0, height)
	for r := 0; r < height; r++ {
		if board[r][0] == 'X' {
			xSeeds = append(xSeeds, [2]int{r, 0})
		}
	}
	right := width - 1
	if floodFill('X', xSeeds, func(r, c int) bool { return c == right }) {
		return "X", nil
	}

	// O plays from top to bottom: any O in the top row reaching the bottom row.
	oSeeds := make([][2]int, 0, width)
	for c := 0; c < width; c++ {
		if board[0][c] == 'O' {
			oSeeds = append(oSeeds, [2]int{0, c})
		}
	}
	bottom := height - 1
	if floodFill('O', oSeeds, func(r, c int) bool { return r == bottom }) {
		return "O", nil
	}

	return "", nil
}

